    const tol = options.tol ?? 1e-6;
    const S = Array.from(Sigma, (r) => Array.from(r));
    if (S.some((r) => r.length !== S[0].length))
        throw new TypeError("all rows of the matrix must have the same length");
    const p = mu.length;
